\label{tab:crossfamily}
\small
\begin{tabular}{lcccc}
\toprule
Family & Clean $\ell z^*$ & Std & $\Delta\ell z^*$ & $d$ \\
\midrule
Qwen-2.5-7B & 8.68 & 1.41 & $-4.83$ & $-3.42$ \\
Llama-3.1-8B & $-0.14$ & 0.97 & $-2.85$ & $-2.95$ \\
Mistral-7B & 5.35 & 1.20 & $-6.73$ & $\mathbf{-5.61}$ \\
